interface StackMapMetadata {
  key: 'schemaVersion'
  value: number
}

export class StackMapDatabase extends Dexie {
  services!: EntityTable<Service, 'id'>
  hosts!: EntityTable<Host, 'id'>
  metadata!: EntityTable<StackMapMetadata, 'key'>

  constructor(name = 'stackmap') {
    super(name)
    this.version(1).stores({
      services: 'id, name, status, hostId, network, exposure, updatedAt',
      hosts: 'id, name, type, updatedAt',
    })
    this.version(2)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
    this.version(3)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<Service, 'id'>('services')
          .toCollection()
          .modify((service) => {
            service.containerName ??= ''
            service.dockerImage ??= ''
            service.description ??= ''
            service.applicationUrl ??= ''
          })
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
    this.version(4)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<Record<string, unknown>, 'id'>('services')
          .toCollection()
          .modify((service) => {
            const configPath = typeof service.configPath === 'string' ? service.configPath : ''
            const dataPath = typeof service.dataPath === 'string' ? service.dataPath : ''
            service.paths = migrateLegacyPaths(String(service.id), { configPath, dataPath })
            delete service.configPath
            delete service.dataPath
          })
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
  }
}

export class DexieStackMapRepository implements StackMapRepository {
  constructor(private readonly database = new StackMapDatabase()) {}

  async getAll(): Promise<StackMapData> {
    await this.getSchemaVersion()
    const [services, hosts] = await Promise.all([
      this.database.services.toArray(),
      this.database.hosts.toArray(),
    ])
    return { services, hosts }
  }

  async putService(service: Service) {
    if (service.hostId && !(await this.database.hosts.get(service.hostId))) {
      throw new Error('The selected host no longer exists.')
    }
    const dependencyCount = await this.database.services
      .where('id')
      .anyOf(service.dependencyIds)
      .count()
    if (dependencyCount !== new Set(service.dependencyIds).size) {
      throw new Error('One or more selected dependencies no longer exist.')
    }
    await this.database.services.put(service)
  }

  async deleteService(id: string) {
    await this.database.transaction('rw', this.database.services, async () => {
      await this.database.services.delete(id)
      const dependents = await this.database.services
        .filter((service) => service.dependencyIds.includes(id))
        .toArray()
      await this.database.services.bulkPut(
        dependents.map((service) => ({
          ...service,
          dependencyIds: service.dependencyIds.filter((dependencyId) => dependencyId !== id),
          updatedAt: new Date().toISOString(),
        })),
      )
    })
  }

  async putHost(host: Host) {
    await this.database.hosts.put(host)
  }

  async deleteHost(id: string) {
    const referenceCount = await this.database.services.where('hostId').equals(id).count()
    if (referenceCount > 0) {
      throw new Error('This host is assigned to one or more services.')
    }
    await this.database.hosts.delete(id)
  }

  async replaceAll(data: StackMapData) {
    await this.database.transaction(
      'rw',
      this.database.services,
      this.database.hosts,
      async () => {
        await Promise.all([this.database.services.clear(), this.database.hosts.clear()])
        await this.database.services.bulkAdd(data.services)
        await this.database.hosts.bulkAdd(data.hosts)
      },
    )
  }

  async getSchemaVersion() {
    const metadata = await this.database.metadata.get('schemaVersion')
    if (!metadata) {
      await this.database.metadata.put({
        key: 'schemaVersion',
        value: CURRENT_SCHEMA_VERSION,
      })
      return CURRENT_SCHEMA_VERSION
    }
    return metadata.value
  }
}

import { validateImport } from '../domain/schema'
import type { StackMapData } from '../domain/types'

export interface LegacyInventoryReader {
  detect(): Promise<boolean>
  read(): Promise<StackMapData>
}

export class LegacyInventoryError extends Error {
  constructor(message: string, readonly code: 'UNSUPPORTED_ENUMERATION' | 'UNSUPPORTED_SCHEMA' | 'DETECTION_FAILED' | 'TIMEOUT') {
    super(message)
    this.name = 'LegacyInventoryError'
  }
}

type LegacySnapshot = { version: number; services: unknown[]; hosts: unknown[] }

export class IndexedDbLegacyInventoryReader implements LegacyInventoryReader {
  constructor(
    private readonly databaseName = 'stackmap',
    private readonly timeoutMs = 10_000,
  ) {}

  async detect(): Promise<boolean> {
    const snapshot = await this.snapshot()
    return snapshot.services.length > 0 || snapshot.hosts.length > 0
  }

  async read(): Promise<StackMapData> {
    const snapshot = await this.snapshot()
    // Dexie encodes version 4 as IndexedDB version 40; hand-created compatibility
    // databases used by older deployments may expose the literal version 4.
    if (snapshot.version !== 4 && snapshot.version !== 40) throw new LegacyInventoryError(
      'Only exact legacy browser schema version 3 can be migrated.',
      'UNSUPPORTED_SCHEMA',
    )
    const normalized = validateImport({
      schemaVersion: 3,
      exportedAt: new Date().toISOString(),
      services: snapshot.services,
      hosts: snapshot.hosts,
    })
    return { services: normalized.services, hosts: normalized.hosts }
  }

  private async snapshot(): Promise<LegacySnapshot> {
    if (!(await databaseExists(this.databaseName, this.timeoutMs))) return { version: 0, services: [], hosts: [] }
    return new Promise((resolve, reject) => {
      let settled = false
      let database: IDBDatabase | undefined
      let transaction: IDBTransaction | undefined
      const request = indexedDB.open(this.databaseName)
      const finish = (error?: Error, snapshot?: LegacySnapshot) => {
        if (settled) return
        settled = true
        globalThis.clearTimeout(timeout)
        if (transaction) transaction.onerror = transaction.onabort = transaction.oncomplete = null
        database?.close()
        if (error) reject(error)
        else resolve(snapshot as LegacySnapshot)
      }
      const timeout = globalThis.setTimeout(() => finish(new LegacyInventoryError(
        'Checking legacy browser data took too long. Retry the safety check.',
        'TIMEOUT',
      )), this.timeoutMs)
      request.onerror = () => finish(new LegacyInventoryError('Legacy browser data could not be read.', 'DETECTION_FAILED'))
      request.onblocked = () => finish(new LegacyInventoryError('Legacy browser data is currently unavailable.', 'DETECTION_FAILED'))
      request.onupgradeneeded = () => {
        const openedDatabase = request.result
        try { request.transaction?.abort() } catch { /* The request still fails closed below. */ }
        openedDatabase.close()
        finish(new LegacyInventoryError('Legacy browser data changed before it could be read safely.', 'DETECTION_FAILED'))
      }
      request.onsuccess = () => {
        if (settled) {
          request.result.close()
          return
        }
        const openedDatabase = request.result
        database = openedDatabase
        const names = openedDatabase.objectStoreNames
        if (!names.contains('services') || !names.contains('hosts')) {
          finish(undefined, { version: openedDatabase.version, services: [], hosts: [] })
          return
        }
        try {
          transaction = openedDatabase.transaction(['services', 'hosts'], 'readonly')
        } catch {
          finish(new LegacyInventoryError('Legacy browser data could not be read.', 'DETECTION_FAILED'))
          return
        }
        const servicesRequest = transaction.objectStore('services').getAll()
        const hostsRequest = transaction.objectStore('hosts').getAll()
        transaction.onerror = () => finish(new LegacyInventoryError('Legacy browser data could not be read.', 'DETECTION_FAILED'))
        transaction.onabort = () => finish(new LegacyInventoryError('Legacy browser data could not be read.', 'DETECTION_FAILED'))
        transaction.oncomplete = () => {
          finish(undefined, {
            version: openedDatabase.version,
            services: servicesRequest.result,
            hosts: hostsRequest.result,
          })
        }
      }
    })
  }
}

async function databaseExists(name: string, timeoutMs: number): Promise<boolean> {
  if (typeof indexedDB.databases !== 'function') {
    throw new LegacyInventoryError(
      'This browser cannot safely enumerate legacy browser databases.',
      'UNSUPPORTED_ENUMERATION',
    )
  }
  let timeout: ReturnType<typeof setTimeout> | undefined
  try {
    const databases = await Promise.race([
      indexedDB.databases(),
      new Promise<never>((_resolve, reject) => {
        timeout = globalThis.setTimeout(() => reject(new LegacyInventoryError(
          'Checking legacy browser data took too long. Retry the safety check.',
          'TIMEOUT',
        )), timeoutMs)
      }),
    ])
    return databases.some((database) => database.name === name)
  } catch (error) {
    if (error instanceof LegacyInventoryError) throw error
    throw new LegacyInventoryError('Legacy browser data could not be checked safely.', 'DETECTION_FAILED')
  } finally {
    if (timeout !== undefined) globalThis.clearTimeout(timeout)
  }
}

export const legacyInventoryReader = new IndexedDbLegacyInventoryReader()

import Dexie, { type EntityTable } from 'dexie'
import { afterEach, describe, expect, it } from 'vitest'
import { createService } from '../domain/serviceUtils'
import type { Host, Service } from '../domain/types'
import { createUuid } from '../utils/uuid'
import { DexieStackMapRepository, StackMapDatabase } from './database'

const databaseNames: string[] = []

function uniqueDatabaseName() {
  const name = `stackmap-test-${createUuid()}`
  databaseNames.push(name)
  return name
}

afterEach(async () => {
  await Promise.all(databaseNames.splice(0).map((name) => Dexie.delete(name)))
})

describe('DexieStackMapRepository', () => {
  it('persists records and stores the local schema version', async () => {
    const database = new StackMapDatabase(uniqueDatabaseName())
    const repository = new DexieStackMapRepository(database)
    expect(database.verno).toBe(4)
    await repository.putService(createService('Persistent service'))

    expect(await repository.getSchemaVersion()).toBe(3)
    expect((await repository.getAll()).services[0].name).toBe('Persistent service')

    database.close()
    const reopened = new DexieStackMapRepository(new StackMapDatabase(database.name))
    expect((await reopened.getAll()).services[0].name).toBe('Persistent service')
  })

  it('migrates an existing version 1 database without losing records', async () => {
    const name = uniqueDatabaseName()
    class LegacyDatabase extends Dexie {
      services!: EntityTable<Service, 'id'>
      hosts!: EntityTable<Host, 'id'>

      constructor() {
        super(name)
        this.version(1).stores({
          services: 'id, name, status, hostId, network, exposure, updatedAt',
          hosts: 'id, name, type, updatedAt',
        })
      }
    }

    const current = {
      ...createService('Legacy service'),
      hostId: 'host-1',
      dependencyIds: ['dependency-1'],
      ports: [{ hostPort: 8080, containerPort: 80, protocol: 'tcp' as const, description: 'web' }],
      configPath: '/srv/appdata/legacy',
      dataPath: '/srv/data/legacy',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-02-01T00:00:00.000Z',
    }
    const legacyService: Record<string, unknown> = { ...current }
    delete legacyService.containerName
    delete legacyService.dockerImage
    delete legacyService.description
    delete legacyService.applicationUrl
    delete legacyService.paths
    const legacy = new LegacyDatabase()
    await legacy.services.add(legacyService as unknown as Service)
    legacy.close()

    const repository = new DexieStackMapRepository(new StackMapDatabase(name))
    expect(await repository.getSchemaVersion()).toBe(3)
    const migrated = (await repository.getAll()).services[0]
    const currentWithoutLegacy: Record<string, unknown> = { ...current }
    delete currentWithoutLegacy.configPath
    delete currentWithoutLegacy.dataPath
    expect(migrated).toEqual({
      ...currentWithoutLegacy,
      containerName: '',
      dockerImage: '',
      description: '',
      applicationUrl: '',
      paths: [
        { id: `${current.id}-configuration-path`, hostPath: '/srv/appdata/legacy', containerPath: '', purpose: 'Configuration', readOnly: false },
        { id: `${current.id}-data-path`, hostPath: '/srv/data/legacy', containerPath: '', purpose: 'Data', readOnly: false },
      ],
    })
  })

  it('keeps existing data when replacement fails', async () => {
    const database = new StackMapDatabase(uniqueDatabaseName())
    const repository = new DexieStackMapRepository(database)
    await repository.putService(createService('Keep me'))
    const duplicate = createService('Duplicate ID')

    await expect(
      repository.replaceAll({
        services: [duplicate, { ...duplicate, name: 'Second duplicate' }],
        hosts: [],
      }),
    ).rejects.toThrow()

    expect((await repository.getAll()).services.map((service) => service.name)).toEqual(['Keep me'])
  })

  it('migrates version 3 fixed paths individually and ignores empty values', async () => {
    const name = uniqueDatabaseName()
    class VersionThreeDatabase extends Dexie {
      services!: EntityTable<Service, 'id'>
      constructor() {
        super(name)
        this.version(3).stores({ services: 'id, name, status, hostId, network, exposure, updatedAt' })
      }
    }
    const legacy = new VersionThreeDatabase()
    const makeLegacy = (id: string, configPath: string, dataPath: string) => {
      const record: Record<string, unknown> = { ...createService(id), id, configPath, dataPath }
      delete record.paths
      return record as unknown as Service
    }
    await legacy.services.bulkAdd([
      makeLegacy('config-only', '/config', ''),
      makeLegacy('data-only', '', '/data'),
      makeLegacy('empty', '', ''),
    ])
    legacy.close()

    const migrated = (await new DexieStackMapRepository(new StackMapDatabase(name)).getAll()).services
    expect(migrated.find((service) => service.id === 'config-only')?.paths).toMatchObject([
      { hostPath: '/config', purpose: 'Configuration', readOnly: false },
    ])
    expect(migrated.find((service) => service.id === 'data-only')?.paths).toMatchObject([
      { hostPath: '/data', purpose: 'Data', readOnly: false },
    ])
    expect(migrated.find((service) => service.id === 'empty')?.paths).toEqual([])
  })
})

